}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    m = pyo.ConcreteModel()

    m.centers = pyo.Set(initialize=d["centers"], ordered=True)
    m.stores = pyo.Set(initialize=d["stores"], ordered=True)
    m.links = pyo.Set(
        dimen=2,
        initialize=[(i, j) for i in d["centers"] for j in d["stores"]],
        ordered=True,
    )

    m.y = pyo.Var(m.centers, domain=pyo.Binary)
    m.x = pyo.Var(m.links, domain=pyo.NonNegativeReals)

    def objective_rule(model):
        opening = sum(d["opening_cost"][i] * model.y[i] for i in model.centers)
        shipping = sum(
            d["transport_cost"][(i, j)] * model.x[i, j] for (i, j) in model.links
        )
        return opening + shipping

    m.obj = pyo.Objective(rule=objective_rule, sense=pyo.minimize)

    def demand_rule(model, j):
        return sum(model.x[i, j] for i in model.centers) >= d["demand"][j]

    m.demand_satisfaction = pyo.Constraint(m.stores, rule=demand_rule)

    def capacity_rule(model, i):
        return (
            sum(model.x[i, j] for j in model.stores)
            <= d["capacity"][i] * model.y[i]
        )

    m.capacity_link = pyo.Constraint(m.centers, rule=capacity_rule)

    return m
